  switch (name) {
    case 'quote-ready': {
      const draft = quoteDraftFor({
        ...MESSAGE,
        id: 'orig-1',
        seq: 4,
        // 원본은 **타인**이 썼다 (N-7). `MESSAGE` 를 그대로 펼치면 저자가
        // `SELF` 라 행 저자와 인용 저자가 같은 이름으로 찍힌다.
        authorMemberId: OTHER,
