      pinned={pinned}
      authorLabel="곽성재"
      onClose={() => {}}
      onToggleReaction={() => {}}
      onReply={() => {}}
      onQuote={() => {}}
      onCopy={() => {}}
      onPin={() => {}}
      onEdit={() => {}}
      onDelete={() => {}}
    />
  );
  const sheet = (confirm: boolean) => (
    <MessageActionSheet
      message={MESSAGE}
      chips={CHIPS}
      availability={AVAILABILITY}
      authorLabel="곽성재"
      startInDeleteConfirm={confirm}
      onClose={() => {}}
      onToggleReaction={() => {}}
      onReply={() => {}}
