            ].join('\n')}
          />
        </Frame>
      );
    case 'markdown-pending':
      return (
        <Frame label="본문 렌더 · 보내는 중 — 코드까지 함께 흐려진다 (H-4)">
          <MessageBody
            body={['보내는 중입니다', '', '```sh', 'echo hi', '```'].join('\n')}
            muted
          />
        </Frame>
      );
    case 'sheet':
      return (
        <Frame label="길게 누르기 시트 — 반응·답글·인용·복사·고정·고치기·지우기·닫기">
          <Row />
          {sheet(false)}
        </Frame>
