const buildStyles = (color: Palette) => StyleSheet.create({
    lockedFrame: {paddingHorizontal: 16, paddingTop: 8},
    // 하네스 자신의 라벨. 제품이 아니라 **사진의 캡션**이라 토큰을 든다: 라이트
