    rejectBox: {gap: space.sm},
    input: {
      minHeight: TOUCH_TARGET * 2,
      borderRadius: ds2Radius.row,
      borderWidth: 1,
      borderColor: color.textFaint,
      backgroundColor: color.surface,
      paddingHorizontal: space.md,
      paddingVertical: space.sm,
