import { uuidEq, type WorkSession } from "../../lib/api";
import { humanSignatureRefusal } from "../auth/humanSignature";
import { SCOPE_UNSUPPORTED_LINE, SignerRefusal, type PermissionScope } from "../auth/signedControl";
import {
