import { buildMode } from "../../runtime/host";
// =============================================================================
// 이 서버가 아직 싣지 않은 표면 (goal B12 / QA H1).
//
// 이 클라이언트는 Swift 서버의 계약을 보고 자랐고, 지금 이야기하는 상대는 그
// 계약의 일부만 이식한 Rust 서버다. 그래서 화면 여럿이 **없는 경로를 부르고 그
// 404를 장애로 그렸다**. 사용자 자리에서 그것은 "이 앱은 고장났다"로 읽힌다.
// 없는 기능을 장애라고 말하는 것은 있는 기능을 없다고 말하는 것과 같은 크기의
// 거짓말이라, 고칠 것은 배너의 문구가 아니라 판정이다.
//
// 여기는 **그 판정이 사는 한 곳**이다. 표면별 제공 여부가 코드 여기저기 흩어지면
// 다음 배치가 라우트를 이식하고도 화면은 계속 "준비 중"이라고 말한다. 이식하는
// 사람이 고쳐야 할 것은 아래 표의 `provided: false` 한 줄이어야 한다.
// 예외는 `HOST_GATED_SURFACE_IDS`의 셋이다(#2780): 서버는 이미 싣고 있고, 펼칠지는
// 그 워크스페이스에 온라인 호스트가 있는가라는 런타임 사실이 정한다.
//
// ## 두 겹으로 막는다
//
//   (a) **정적 판정** — 아래 표. 진입점을 세울지 말지를 정한다. 요청을 한 번도
//       보내지 않고 답하므로, 없는 표면은 404를 만들지조차 않는다.
//   (b) **런타임 접기** — `serverSaysAbsent`. 표가 틀렸거나(서버가 우리보다
//       앞서 갔거나 뒤처졌거나) 표에 없는 경로가 404를 받으면, 그것을 오류가
//       아니라 "미제공"으로 접는다.
//
// (a)만 있으면 표가 곧 거짓말이 되고, (b)만 있으면 모든 화면이 일단 실패한 뒤에야
// 정직해진다. 둘 다 필요하다.
//
// ## 미제공과 장애는 다른 문장이다
//
// 사용자는 "내 인터넷 문제"와 "아직 없는 기능"을 구분할 수 있어야 한다. 전자는
// 다시 시도할 일이고 후자는 기다릴 일이다. 그래서 `serverSaysAbsent`가 참인
// 것만 미제공 문구를 받고, 네트워크 장애·5xx·401/403은 기존 오류/오프라인
// 문구를 그대로 쓴다. 이 규칙은 이 파일이 발명한 것이 아니라 이미 이 코드베이스가
// 쓰던 것이다(features/routing/capability.ts, features/huddles/huddleModel.ts).
//
// ## 실측 방법과 시점
//
// 2026-08-02, `server-rust/bins/momo-server/src/lib.rs`의 등록된 라우트 55개를
// 클라이언트가 부르는 모든 `/v1/` 경로와 **메서드까지 맞춰** 대조했다. 경로만
// 비교하면 그때의 `agentRunHistory`를 놓쳤다: 그 경로는 POST로만 등록돼 있어서
// GET은 404가 아니라 **405**로 돌아왔다(#1223이 GET을 같은 `.route()`에 얹어
// 그 405를 없앴다). 메서드까지 맞춰 대조하는 규율은 그래서 남는다 — 다음에
// 어떤 표면이 같은 모양으로 반쪽만 서 있어도 이 표가 그것을 본다.
// =============================================================================

import { ApiError } from "../../lib/api";

/**
 * 서버가 "그런 경로 없다"고 **직접 답한** 상태 코드.
 *
 * 이 셋만 "없다"로 읽는다. 401/403은 권한 이야기이고, 5xx는 서버가 아팠다는
 * 뜻이며, 네트워크 실패는 아무도 답하지 않은 것이라 셋 다 기능 유무에 대한
 * 진술이 아니다. 그것들을 "미제공"으로 접으면 이 파일은 반대 방향의 거짓말을
 * 하게 된다: 잠깐 아픈 서버를 영영 없는 기능으로 만든다.
 *
 * 405가 들어 있는 이유는 취향이 아니라 실측이다. `GET …/channels/{ch}/agent-runs`
 * 는 경로가 POST 전용으로 등록돼 있어 405로 돌아왔다. 404만 보는 판정은 그 표면을
 * 장애로 그렸다. #1223이 그 GET을 올려 이 예시 자체는 과거가 됐지만 405는 남는다:
 * 반쪽만 선 경로는 이 서버에서 실제로 일어나는 일이고, 그날 405를 빼면 판정은 또
 * 같은 자리에서 "고장"이라고 말한다.
 */
export const ABSENT_STATUSES: readonly number[] = [404, 405, 501];

/**
 * 이 오류가 "이 서버에는 그 기능이 없다"는 서버의 답인가.
 *
 * 참이면 미제공 상태로 접고, 거짓이면 기존 오류 처리를 그대로 태운다.
 */
export function serverSaysAbsent(error: unknown): boolean {
  return error instanceof ApiError && ABSENT_STATUSES.includes(error.status);
}

export type SurfaceId =
  | "workstreams"
  | "workConsole"
  | "work"
  | "ade"
  | "approvals"
  | "huddles"
  | "agentRunHistory"
  | "plugins"
  | "agentMemory"
  | "messageSearch"
  | "hostedAgentPairing";

/** Workd/T3 데몬을 전제하는 표면. 셀프호스트 기본은 모두 숨긴다 (ADR-0183 D4-② · #2166). */
export const WORK_SURFACE_IDS: readonly SurfaceId[] = [
  "workstreams",
  "workConsole",
  "work",
  "ade",
];

/**
 * 정적 표가 아니라 **런타임 사실**로 펼치는 작업 표면 (#2780, 작업 공간 M2).
 *
 * 이 셋은 서버 라우트가 이미 서 있다. 모자란 것은 서버가 아니라 그 워크스페이스에
 * 붙은 코드 실행 호스트다. 그래서 「이 서버가 싣는가」라는 표의 질문으로는 답이
 * 안 나오고, 표를 손으로 뒤집으면 호스트가 없는 셀프호스트에서 막다른 길이 선다.
 * 판정은 「이 워크스페이스에 온라인 호스트가 있는가」로 한다(`hasOnlineWorkHost`).
 * 셋 다 관전·관제 표면이라 남의 개인 호스트도 센다(#2854 planner 결정 (a)).
 *
 * `workstreams`는 여기 없다: 그 라우트는 아직 서버에 없다(404). 호스트가 있어도
 * 열 곳이 없다.
 *
 * 로컬 터미널 레인(데스크탑 ⌃`, ADR-0190 D1)은 이 판정 밖이다. 호스트 없이도
 * 데스크탑이면 선다.
 */
export const HOST_GATED_SURFACE_IDS: readonly SurfaceId[] = [
  "workConsole",
  "work",
  "ade",
];

/** 호스트 목록에서 표면 판정이 읽는 두 칸. */
export interface WorkHostPresenceFact {
  online: boolean;
  revokedAtMs?: number | null;
}

/**
 * 이 호스트로 **일을 시킬 수 있는가**(시작·조작 표면 전용, #2893·#2854 planner 결정 (a)).
 *
 * 개인 호스트(`scope=member`)는 주인만 일을 시킨다(ADR-0188 D4, ADR-0192). 팀 공용
 * 호스트(`scope=workspace`)는 누구나. 세션 이어받기 대상(`workSessionResumeTargets`)이
 * 이 판정을 쓴다.
 *
 * **관전·관제 표면에는 쓰지 않는다.** 서버는 채널 멤버에게 남의 개인 호스트 세션의
 * 목록과 관전을 허락한다(`momo-t3` lifecycle·terminal_attach). 그래서 작업 콘솔·관제
 * 줄·관제 서랍·관전 도크는 `hasOnlineWorkHost`(누구의 호스트든 온라인이면)로 선다.
 */
export function isWorkHostUsableBy(
  host: { scope: "member" | "workspace"; ownerMemberId: string },
  selfMemberId: string
): boolean {
  if (host.scope === "workspace") return true;
  return host.ownerMemberId.toLowerCase() === selfMemberId.toLowerCase();
}

/**
 * 이 워크스페이스에 지금 온라인인 호스트가 하나라도 있는가(관전·관제 표면의 판정).
 *
 * `online`은 서버의 90초 heartbeat 창이다(`work_host_store.rs`). 해지된 호스트는
 * heartbeat가 남아 있어도 세지 않는다. 목록을 아직 받지 못했으면(`undefined`)
 * 거짓이다: 모르는 것을 있다고 그리면 누른 뒤에야 빈 화면을 만난다. 주인은 따지지
 * 않는다: 남의 개인 호스트 세션도 채널 멤버는 볼 수 있다(`isWorkHostUsableBy` 주석).
 */
export function hasOnlineWorkHost(
  hosts: readonly WorkHostPresenceFact[] | null | undefined
): boolean {
  if (!hosts) return false;
  return hosts.some(
    (host) =>
      host.online === true &&
      (host.revokedAtMs === undefined || host.revokedAtMs === null)
  );
}

/**
 * 정적 판정과 런타임 사실을 합친 표면 판정.
 *
 * `staticProvided`는 호출하는 쪽이 `isSurfaceProvided(id)`로 구해 넘긴다. 여기서
 * 직접 부르지 않는 이유는 시험 이음매다: 화면 시험이 정적 절반을 모듈 경계에서
 * 바꿔 끼울 수 있어야 런타임 절반만 따로 잴 수 있다.
 */
export function surfaceProvidedWithHosts(
  id: SurfaceId,
  staticProvided: boolean,
  onlineHost: boolean
): boolean {
  if (staticProvided) return true;
  return HOST_GATED_SURFACE_IDS.includes(id) && onlineHost;
}

export interface ServerSurface {
  id: SurfaceId;
  /**
   * 사용자가 이 표면을 부르는 이름. 화면 문구가 이 말을 쓴다.
   *
   * **가는 길도 이 말을 쓴다** (이슈 #1146 N4). 진입점이 자기 낱말을 따로 적으면
   * 한 목적지에 이름이 둘 생기고, 그 순간 사람은 그것을 두 기능으로 센다 —
   * 팔레트가 이미 「멤버 ↔ 디렉터리」에서 같은 값을 치르고 한 이름으로 모았다
   * (`QuickSwitcher` R-1 어휘 계승). 그래서 이 필드는 「없을 때 할 말」의 재료가
   * 아니라 **그 표면의 이름 자체**이고, 사이드바 줄·팔레트 항목·라우트의 제목이
   * 함께 읽는다.
   */
  label: string;
  /** 이 서버가 이 표면의 REST를 싣고 있는가 (2026-08-02 실측). */
  provided: boolean;
  /**
   * 못 하는 이유 한 문장. 내부 용어·코드명·경로·상태 코드를 쓰지 않는다:
   * 읽는 사람은 이 서버를 고르는 사람이지 이 서버를 만드는 사람이 아니다.
   */
  absentReason: string;
  /** 대신 지금 할 수 있는 일. 없는 표면 앞에서 사용자를 막다른 길에 두지 않는다. */
  fallback: string;
  /**
   * 실측 근거. 사용자에게 보이지 않는다. 다음 배치가 이 줄을 다시 재지 않고
   * 믿을 수 있게, 무엇을 무엇과 대조했는지 남긴다.
   */
  measured: string;
}

